const triples = {
  "darwin-arm64":     "@livekit/blingfire-darwin-arm64",
  "darwin-x64":       "@livekit/blingfire-darwin-x64",
  "linux-x64":        "@livekit/blingfire-linux-x64-gnu",
  "linux-arm64":      "@livekit/blingfire-linux-arm64-gnu",
  "linux-x64-musl":   "@livekit/blingfire-linux-x64-musl",
  "linux-arm64-musl": "@livekit/blingfire-linux-arm64-musl",
  "win32-x64":        "@livekit/blingfire-win32-x64-msvc",
};

// Same check as napi-rs: ldd names its libc; fall back to the process
// report, which only carries glibcVersionRuntime on glibc.
function isMusl() {
  try {
    return require("fs").readFileSync("/usr/bin/ldd", "utf8").includes("musl");
  } catch {}
  try {
    return !process.report.getReport().header.glibcVersionRuntime;
  } catch {
    return false;
  }
}

const libc = process.platform === "linux" && isMusl() ? "-musl" : "";
const key = `${process.platform}-${process.arch}${libc}`;
const subpkg = triples[key];
if (!subpkg) {
  throw new Error(
    `@livekit/blingfire: no prebuilt binary for ${key}. ` +
    `Supported: ${Object.keys(triples).join(", ")}.`
  );
}

let binding;
try {
  binding = require(subpkg);
} catch (subErr) {
  // Fall back to a locally-built .node (build/Release or prebuilds/)
  // so `pnpm link` / local checkouts work without the sub-package.
  try {
    binding = require("node-gyp-build")(__dirname);
  } catch {
    const err = new Error(
      `@livekit/blingfire: failed to load ${subpkg}. ` +
      `Re-run \`npm install\` (or \`pnpm install\`) so the optional ` +
      `platform dependency for ${key} is fetched.`
    );
    err.cause = subErr;
    throw err;
  }
}

module.exports = {
  textToSentences: binding.textToSentences,
  textToSentencesWithOffsets: binding.textToSentencesWithOffsets,
  textToWords: binding.textToWords,
  textToWordsWithOffsets: binding.textToWordsWithOffsets,
};
